import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import vm from 'node:vm';
import {calculateTax,parseIncome,parsePayg,InputError,MAX_INCOME} from '../src/model.mjs';
import {render} from '../build.mjs';
// Independent expected dollar fixtures supplied by the task, never generated by model.
const fixtures = [
[0,0,0,0,0],[18201,.16,.16,0,0],[22575,700,700,0,0],[22576,700.16,700,0,.16],
[28011,1569.76,700,0,869.76],[28012,1569.92,700,.10,870.02],[29000,1728,700,98.90,1126.90],
[35013,2690.08,700,700.20,2690.28],[35014,2690.24,700,700.28,2690.52],
[37500,3088,700,750,3138],[37501,3088.16,699.95,750.02,3138.23],
[45000,4288,325,900,4863],[45001,4288.30,324.99,900.02,4863.33],
[50000,5788,250,1000,6538],[66666,10787.80,.01,1333.32,12121.11],
[66667,10788.10,0,1333.34,12121.44],[100000,20788,0,2000,22788],
[135000,31288,0,2700,33988],[190000,51638,0,3800,55438],[250000,78638,0,5000,83638]
];
for (const [income,gross,lito,med,total] of fixtures) test(`independent fixture $${income}`,()=> {
 const r=calculateTax({taxableIncome:String(income)});
 assert.deepEqual([r.grossTaxCents,r.litoAppliedCents,r.medicareCents,r.totalTaxCents], [gross,lito,med,total].map(n=>Math.round(n*100)));
});
for (const [income,gross,total] of [[18199,0,0],[18200,0,0],[44999,4287.84,4862.77],[134999,31287.70,33987.68],[135001,31288.37,33988.39],[189999,51637.63,55437.61],[190001,51638.45,55438.47]])
 test(`independent boundary $${income}`,()=>{const r=calculateTax({taxableIncome:income});assert.equal(r.grossTaxCents,Math.round(gross*100));assert.equal(r.totalTaxCents,Math.round(total*100));});
for (const value of ['', ' ', '-1', -1, 1.5, '1.2','1.0','100,000','1e5','0x10','Infinity',Infinity,NaN,'NaN',null,undefined,{},[],true,'+100','1_000','１２３',String(MAX_INCOME+1)])
 test(`reject income ${String(value)} (${typeof value})`,()=>assert.throws(()=>calculateTax({taxableIncome:value}),InputError));
test('whole dollars, leading zeros and surrounding whitespace accepted',()=>assert.equal(parseIncome(' 00100 '),100n));
test('blank PAYG differs from explicit zero',()=>{const a=calculateTax({taxableIncome:100000});const b=calculateTax({taxableIncome:100000,paygWithheld:'0'});assert.equal(a.paygDifferenceCents,null);assert.equal(a.balanceKind,null);assert.equal(b.paygDifferenceCents,-2278800);assert.equal(b.balanceKind,'payable');});
test('PAYG refund $2212 on $100k / $25k',()=>{const r=calculateTax({taxableIncome:100000,paygWithheld:'25000'});assert.equal(r.paygDifferenceCents,221200);assert.equal(r.balanceKind,'refund');});
test('PAYG exact and payable cents',()=>{let r=calculateTax({taxableIncome:100000,paygWithheld:'22788.00'});assert.equal(r.balanceKind,'exact');assert.equal(r.paygDifferenceCents,0);r=calculateTax({taxableIncome:100000,paygWithheld:'22787.99'});assert.equal(r.balanceKind,'payable');assert.equal(r.paygDifferenceCents,-1);assert.equal(parsePayg('12.3'),1230n);assert.equal(parsePayg('0.01'),1n);assert.equal(parsePayg('  '),null);});
for(const value of ['-1','1.001','1e3','NaN',NaN,Infinity,null,{},'1,000','.50','1.']) test(`reject PAYG ${String(value)} (${typeof value})`,()=>assert.throws(()=>calculateTax({taxableIncome:100000,paygWithheld:value}),InputError));
test('half-cent LITO rounds up before cap; never offsets Medicare',()=>{assert.equal(calculateTax({taxableIncome:45001}).litoAppliedCents,32499);assert.equal(calculateTax({taxableIncome:66665}).litoAppliedCents,3);assert.equal(calculateTax({taxableIncome:18201}).incomeTaxCents,0);assert.equal(calculateTax({taxableIncome:0}).effectiveRatePercent,0);});
test('monotonic total, integer cents and reconciliation: every dollar 0..300000 plus large values',()=>{let previous=-1;for (const income of [...Array(300001).keys(),1000000,MAX_INCOME]){const r=calculateTax({taxableIncome:income});assert.ok(r.totalTaxCents>=previous,`monotonic at ${income}`);previous=r.totalTaxCents;assert.equal(r.incomeTaxCents+r.litoAppliedCents,r.grossTaxCents);assert.equal(r.totalTaxCents,r.incomeTaxCents+r.medicareCents);assert.equal(r.remainingCents+r.totalTaxCents,income*100);assert.ok(r.litoAppliedCents<=r.grossTaxCents);assert.ok(r.incomeTaxCents>=0);for (const k of ['grossTaxCents','litoAppliedCents','medicareCents','totalTaxCents','remainingCents'])assert.ok(Number.isSafeInteger(r[k]));}});
test('built HTML exactly matches current sources with one embedded engine',async()=>{const html=await readFile(new URL('../index.html',import.meta.url),'utf8');assert.equal(html,await render());assert.equal((html.match(/function calculateTax\(/g)||[]).length,1);assert.doesNotMatch(html,/<script[^>]+src=|<link[^>]+stylesheet|@import|url\(/i);const script=html.match(/<script>([\s\S]*)<\/script>/)[1];const engine=script.split('const form =')[0];const ctx=vm.createContext({});vm.runInContext(engine+'\nglobalThis.model = calculateTax;',ctx);assert.equal(ctx.model({taxableIncome:29000}).totalTaxCents,112690);});
